// Fare: the adult Octopus price to ride a Route from a Stop to its terminus (see GLOSSARY.md).
// The table is generated by `npm run gen:fares`; each Route's list is indexed by seq - 1.

import generatedFares from './generated/fares.json'

export type FareRoute = { route: string; bound: string; service_type: string }
export type FareTable = { [routeKey: string]: number[] }

/** The Fare at a position (`seq`) on a Route; null at the terminus or for a Route without fare data. */
export type FareLookup = (route: FareRoute, seq: string | number) => number | null

export function createFareLookup(table: FareTable): FareLookup {
  return (route, seq) => {
    const fares = table[`${route.route}|${route.bound}|${route.service_type}`]
    return fares?.[Number(seq) - 1] ?? null
  }
}

export const fareFor: FareLookup = createFareLookup(generatedFares as FareTable)
